-- Story mode: curated scene sequences Auto plays in order, a playlist, and the admin "Talk to Auto" chat.
create table if not exists stories (
  id bigserial primary key,
  title text not null check (char_length(title) between 1 and 80),
  theme text not null default '' check (char_length(theme) <= 200),
  scenes jsonb not null default '[]'::jsonb check (jsonb_typeof(scenes) = 'array'),
  archived boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists story_playlist (
  id bigserial primary key,
  story_id bigint not null references stories(id),
  position double precision not null default extract(epoch from now()),
  status text not null default 'queued' check (status in ('queued','playing','done','skipped')),
  scene_index int not null default 0,
  started_at timestamptz, finished_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists story_playlist_open on story_playlist(position) where status in ('queued','playing');
create table if not exists auto_chats (
  id bigserial primary key,
  title text not null default 'New chat',
  summary text not null default '',
  summarized_upto bigint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists auto_chat_messages (
  id bigserial primary key,
  chat_id bigint not null references auto_chats(id),
  role text not null check (role in ('user','assistant')),
  content jsonb not null,
  created_at timestamptz not null default now()
);
create index if not exists auto_chat_messages_chat on auto_chat_messages(chat_id, id);
alter table stories enable row level security;
alter table story_playlist enable row level security;
alter table auto_chats enable row level security;
alter table auto_chat_messages enable row level security;
insert into stories(title,theme,scenes) select * from (values
('Ancient Egypt','the Nile kingdoms at their height','[{"title": "Giza at Dawn", "prompt": "the great pyramids of Giza at golden dawn, aerial ultra-wide, sun rising behind smooth white limestone casing, palm groves and the Nile glittering, dust haze, cinematic photo, 24mm"}, {"title": "Temple Colonnade", "prompt": "colossal painted columns of Karnak temple receding into shafts of light, hieroglyph reliefs in red ochre and lapis, incense smoke, low angle, cinematic photo"}, {"title": "Tomb Passage", "prompt": "torch-lit descending tomb corridor, walls covered in vivid painted hieroglyphs and gods, gold leaf glinting, deep shadows, dust motes, 35mm"}, {"title": "Burial Chamber", "prompt": "vast burial chamber with a carved granite sarcophagus, starry blue ceiling painted with gold stars, offerings of jars and chariots, warm lamplight"}, {"title": "Golden Pharaoh", "prompt": "extreme close-up of a pharaoh''s golden death mask in an open sarcophagus, inlaid lapis and carnelian, reflections of torchlight, macro, rich detail"}, {"title": "The Mummy", "prompt": "close-up of an ancient linen-wrapped mummy, frayed bandages, amulets of faience scarabs resting on its chest, soft amber light, eerie and beautiful"}, {"title": "Scarab Gold", "prompt": "macro of a jeweled scarab amulet among scattered gold beads and papyrus fragments, shallow depth of field, warm sunbeam through dust"}]'::jsonb),
('Imperial Rome','the Roman Empire in marble and fire','[{"title": "Forum at Noon", "prompt": "the Roman Forum at its height, gleaming marble temples, bronze statues, red roof tiles, distant hills, aerial wide, bright Mediterranean sun, cinematic photo"}, {"title": "Colosseum Arches", "prompt": "low angle up the travertine arches of the Colosseum, banners fluttering, crowds tiny in the distance, late golden light, 24mm"}, {"title": "Arena Floor", "prompt": "inside the Colosseum arena, sand floor, tiered seats rising, velarium awnings casting striped shadows, dust in the air, wide"}, {"title": "Bath Mosaics", "prompt": "steaming Roman bath hall, turquoise pool, floor mosaics of sea creatures, marble columns, shafts of light through high windows"}, {"title": "Senator''s Villa", "prompt": "frescoed villa interior, Pompeian red walls painted with gardens and birds, bronze oil lamps, laurel wreath on a marble table"}, {"title": "Legion Eagle", "prompt": "close-up of a golden legionary aquila standard against a stormy sky, red cloth streaming, rain drops, dramatic light"}, {"title": "Fall of Night", "prompt": "Rome at night from the Palatine hill, thousands of oil lamps and torches, smoke from temples, moonlit aqueduct in the distance"}]'::jsonb),
('Into the Deep','a descent from sunlit reef to the abyss','[{"title": "Sunlit Reef", "prompt": "vibrant coral reef in shallow turquoise water, sun rays rippling, schools of yellow fish, sea fans swaying, underwater photo"}, {"title": "Kelp Cathedral", "prompt": "towering golden kelp forest, light filtering down in green shafts, sea otters tiny above, drifting particles"}, {"title": "Blue Twilight", "prompt": "deep blue open ocean twilight zone, silhouettes of manta rays gliding, a curtain of tiny bioluminescent plankton"}, {"title": "Jellyfish Bloom", "prompt": "dense bloom of glowing translucent jellyfish in dark water, trailing tentacles, pink and cyan bioluminescence, macro"}, {"title": "Anglerfish", "prompt": "close-up of a deep sea anglerfish with a glowing lure in pitch black water, needle teeth, marine snow drifting"}, {"title": "Hydrothermal Vents", "prompt": "black smoker hydrothermal vents on the abyssal floor, plumes of dark mineral water, white tube worms and pale crabs, spotlight from a submersible"}, {"title": "Abyssal Glow", "prompt": "vast abyssal plain lit by a field of bioluminescent creatures like stars, ghostly sea cucumbers, total darkness beyond"}]'::jsonb),
('Tokyo Night','neon Tokyo after midnight','[{"title": "Skyline Rain", "prompt": "aerial view of Tokyo at night in light rain, endless neon towers, glowing streets, low clouds lit pink and blue, cinematic photo"}, {"title": "Crossing Glow", "prompt": "Shibuya crossing from above at night, umbrellas tiny below, giant glowing screens, wet asphalt reflections, long exposure"}, {"title": "Alley Lanterns", "prompt": "narrow Golden Gai alley, red paper lanterns, tiny bars stacked with signs, rain-slick cobbles, steam, 35mm"}, {"title": "Ramen Counter", "prompt": "close-up of a steaming ramen bowl on a wooden counter, chashu, egg, nori, warm lamp light, bokeh of neon behind"}, {"title": "Arcade Lights", "prompt": "interior of a retro arcade, rows of glowing cabinets, pink and teal light, cables and stickers, motion blur"}, {"title": "Last Train", "prompt": "an empty late-night Tokyo train carriage, fluorescent light, city lights streaking past the windows"}, {"title": "Shrine at Dawn", "prompt": "quiet Shinto shrine at blue dawn, vermilion torii gates in a row, stone lanterns, mist, city towers faint behind"}]'::jsonb),
('Cathedral','a gothic cathedral from spire to crypt','[{"title": "Spires in Fog", "prompt": "gothic cathedral spires rising from morning fog over a medieval town, ravens circling, low angle, soft grey light"}, {"title": "West Rose", "prompt": "close-up of a vast stained glass rose window, jewel colors blazing with backlight, intricate stone tracery"}, {"title": "Nave Light", "prompt": "the immense nave of a gothic cathedral, ribbed vaults, shafts of colored light through stained glass, incense haze, wide"}, {"title": "Choir Stalls", "prompt": "carved oak choir stalls with saints and beasts, candlelight, gilded organ pipes rising behind"}, {"title": "Bell Tower", "prompt": "inside the bell tower, huge bronze bells and wooden beams, dust, pigeons, light through louvers"}, {"title": "Gargoyles", "prompt": "close-up of weathered stone gargoyles on a ledge in the rain, water pouring from their mouths, city far below"}, {"title": "Crypt Candles", "prompt": "low vaulted stone crypt lit by hundreds of candles, carved tombs of knights, warm flicker, deep shadow"}]'::jsonb),
('Rainforest Canopy','one day in the rainforest canopy','[{"title": "Misty Canopy", "prompt": "aerial over an endless rainforest canopy at sunrise, mist rising between giant trees, river glinting, drone shot"}, {"title": "Strangler Fig", "prompt": "low angle up a colossal strangler fig tree, buttress roots, lianas hanging, shafts of green light"}, {"title": "Bromeliad Pool", "prompt": "macro of water pooled in a red bromeliad, a tiny blue poison dart frog, droplets, shallow depth of field"}, {"title": "Orchid Branch", "prompt": "close-up of wild orchids and mosses on a high branch, butterflies, soft diffuse light"}, {"title": "Macaw Flight", "prompt": "scarlet macaws flying past a canopy of emerald leaves, motion blur on wings, bright sun"}, {"title": "Afternoon Storm", "prompt": "tropical downpour over the canopy, rain curtains, lightning on the horizon, leaves shining wet"}, {"title": "Firefly Night", "prompt": "rainforest canopy at night, thousands of fireflies, glowing fungi on bark, moonlight through leaves"}]'::jsonb),
('Arctic Light','from glacier to aurora','[{"title": "Glacier Front", "prompt": "towering blue glacier front calving into a dark fjord, floating ice, low sun, aerial wide, cinematic photo"}, {"title": "Ice Cave", "prompt": "inside a glowing blue glacial ice cave, rippled translucent walls, a stream of meltwater, soft light"}, {"title": "Frost Macro", "prompt": "macro of intricate frost crystals and feathers of ice, sparkling, cool blue and white"}, {"title": "Iceberg Drift", "prompt": "a giant sculpted iceberg drifting on mirror-calm water, pink midnight sun, reflections"}, {"title": "Fox in Snow", "prompt": "an arctic fox curled in deep snow, fur rimmed with frost, soft low sun, telephoto"}, {"title": "Frozen Harbor", "prompt": "a tiny fishing harbor of red wooden houses under snow, boats in ice, warm windows, blue hour"}, {"title": "Aurora", "prompt": "vast green and violet aurora over snowy mountains and a frozen lake, stars, long exposure"}]'::jsonb),
('Silk Road','a caravan journey east','[{"title": "Desert Dunes", "prompt": "camel caravan crossing tall golden dunes at sunset, long shadows, wind-blown sand, aerial wide"}, {"title": "Caravanserai", "prompt": "a stone caravanserai courtyard at dusk, lanterns, camels resting, carpets and bundles, warm light"}, {"title": "Spice Bazaar", "prompt": "a covered bazaar heaped with spices, saffron, chilies and cardamom, shafts of light through the roof, dust"}, {"title": "Blue Domes", "prompt": "turquoise tiled domes and minarets of Samarkand under a clear sky, intricate mosaics, low angle"}, {"title": "Silk Bolts", "prompt": "close-up of shimmering silk bolts in jewel colors, embroidered patterns, soft window light"}, {"title": "Mountain Pass", "prompt": "a caravan threading a high snowy mountain pass, prayer flags, thin clouds, dramatic peaks"}, {"title": "Chang''an Gate", "prompt": "the great gate of ancient Chang''an at dusk, red lanterns, tiled roofs stretching away, mist"}]'::jsonb)) v(t,th,s) where not exists (select 1 from stories);
